def affected(lst1, lst2) -> bool:
    def run(even_key):
        def go():
            cnt_odd = sum(1 for x in lst1 if x % 2 == 1)
            cnt_even = sum(1 for x in lst2 if even_key(x))
            return 'YES' if cnt_odd <= cnt_even else 'NO'
        try:
            return ('ok', go())
        except Exception as e:
            return ('err', type(e))
    orig = run(lambda x: x % 2 == 0)
    mut = run(lambda x: x // 2 == 0)
    return orig != mut
